    out_path = os.path.join(here, "heladas.csv")
    rows = []
    for lat, lons in sorted(GRID.items()):
        for lon in lons:
            rows.append((round(lat, 1), round(lon, 1)))

    with open(out_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["lat", "lon"])
        writer.writerows(rows)

    print(f"Generado: {out_path}  ({len(rows)} puntos)")
